it('USD ar-SA', (done) => {
  try {
    const affixes2 = utils.getCurrencyAffixes({
      currency: 'USD',
      decimalLimit: 2,
      decimalSeparator: '٫',
      lang: 'ar-SA',
    });
    const expectedResult = {
      prefix: '',
      suffix: ' US$',
    };
    expect(affixes2.prefix).to.equal(expectedResult.prefix);
    expect(affixes2.suffix).to.equal(expectedResult.suffix);
    done();
  }
  catch (err) {
    done(err);
  }
});

